// Pure types + helpers for the Address Converter (old → new address lookup).
// The data is generated by scripts/generate-address-conversion.mjs into public/data/address*.
// No React / DOM here so this stays unit-testable.

export interface AddressResult {
  newProvince: string;
  newProvinceSlug: string;
  newProvinceCode: string;
  newWard: string;
  newWardShort: string;
  newWardCode: string;
  newWardType: string;
  lat: number | null;
  lon: number | null;
  areaKm2: number | null;
}

export interface AddressWard {
  code: string;
  name: string;
  type: string;
  isDivided: boolean;
  results: AddressResult[];
}

export interface AddressDistrict {
  code: string;
  name: string;
  type: string;
  isIsland: boolean;
  wards: AddressWard[];
  // District-level results, populated for island districts only (no ward level).
  results: AddressResult[];
}

export interface AddressProvinceFile {
  schemaVersion: 1;
  mergeDate: string;
  code: string;
  name: string;
  name_en: string;
  slug: string;
  districts: AddressDistrict[];
}

export interface AddressIndexProvince {
  code: string;
  name: string;
  name_en: string;
  slug: string;
  districtCount: number;
  wardCount: number;
  hasIslandDistrict: boolean;
}

export interface AddressIndex {
  schemaVersion: 1;
  source: Record<string, string>;
  mergeDate: string;
  counts: {
    oldProvinces: number;
    oldWards: number;
    islandDistricts: number;
    oldUnits: number;
    newProvinces: number;
    newWards: number;
    dividedOldWards: number;
  };
  provinces: AddressIndexProvince[];
}

export const ADDRESS_INDEX_URL = '/data/address-index.json';

export function provinceFileUrl(provinceCode: string): string {
  return `/data/address/pre/${provinceCode}.json`;
}

export function findDistrict(
  file: AddressProvinceFile | null,
  districtCode: string | null,
): AddressDistrict | null {
  if (!file || !districtCode) return null;
  return file.districts.find(d => d.code === districtCode) ?? null;
}

export function findWard(
  district: AddressDistrict | null,
  wardCode: string | null,
): AddressWard | null {
  if (!district || !wardCode) return null;
  return district.wards.find(w => w.code === wardCode) ?? null;
}

export interface ResolvedSelection {
  district: AddressDistrict;
  ward: AddressWard | null; // null for island districts (district-level result)
  results: AddressResult[];
  isDivided: boolean;
}

// Resolve a (district, ward) selection to its new-address result(s). Island districts resolve on
// the district alone; normal districts require a ward. Returns null until a resolvable unit is chosen.
export function resolveSelection(
  file: AddressProvinceFile | null,
  districtCode: string | null,
  wardCode: string | null,
): ResolvedSelection | null {
  const district = findDistrict(file, districtCode);
  if (!district) return null;

  if (district.isIsland) {
    if (district.results.length === 0) return null;
    return { district, ward: null, results: district.results, isDivided: false };
  }

  const ward = findWard(district, wardCode);
  if (!ward) return null;
  return { district, ward, results: ward.results, isDivided: ward.results.length > 1 };
}

// The full new-address string, most-specific first (matches how Vietnamese addresses are written
// bottom-up in official forms): "Phường Hồng Hà, Thành phố Hà Nội".
export function formatNewAddress(result: AddressResult): string {
  return `${result.newWard}, ${result.newProvince}`;
}

// The full old-address string for a resolved selection.
export function formatOldAddress(
  province: AddressProvinceFile,
  district: AddressDistrict,
  ward: AddressWard | null,
): string {
  const parts = ward ? [ward.name, district.name, province.name] : [district.name, province.name];
  return parts.join(', ');
}

// ---- URL state (shareable) ----------------------------------------------------------------------
// Query keys: p = old province code, d = old district code, w = old ward code.

export interface AddressSelection {
  p: string | null;
  d: string | null;
  w: string | null;
}

export function parseSelection(params: URLSearchParams): AddressSelection {
  return {
    p: params.get('p') || null,
    d: params.get('d') || null,
    w: params.get('w') || null,
  };
}

export function buildSelectionQuery(selection: AddressSelection): string {
  const params = new URLSearchParams();
  if (selection.p) params.set('p', selection.p);
  if (selection.d) params.set('d', selection.d);
  if (selection.w) params.set('w', selection.w);
  const query = params.toString();
  return query ? `?${query}` : '';
}
